-- Historikal roster update. GENERATED by scripts/build-historikals.mjs --update: the 21 creatures
-- that changed since the catalogue last applied.
insert into public.badge_kinds (slug, title, blurb, art, sort, rarity, element, types, rnd, shift, hearts, moves, droppable, active)
select f[1], f[2],
       'A ' || f[3] || ' ' || initcap(f[4]) || case when f[5] <> '' then '/' || initcap(f[5]) else '' end || ' Historikal.',
       'creatures/' || f[1] || '.png', f[7]::int, f[3], case f[4] when 'fire' then 'fire' when 'tide' then 'water' when 'nature' then 'grass' when 'ward' then 'rock' when 'feral' then 'rock' when 'dark' then 'dark' when 'spirit' then 'light' end,
       case when f[5] <> '' then array[f[4], f[5]] else array[f[4]] end, f[8] = '1', f[9] = '1', f[6]::int,
       (select jsonb_agg(jsonb_build_object('name', split_part(m, ':', 1), 'kind', split_part(m, ':', 2)) order by o)
          from unnest(string_to_array(f[10], ';')) with ordinality as x(m, o)),
       true, true
  from (select string_to_array(l, '|') as f from unnest(string_to_array($cat$
hairy-lurker|HAIRY LURKER|rare|feral|nature|3|1016|0|0|Maul:sword;Overgrow:spell;Thick Hide:armor
jewel-spider|JEWEL SPIDER|uncommon|fire|nature|3|1017|0|0|Scorch:sword;Briar Wall:armor
frost-crawler|FROST CRAWLER|rare|tide|nature|3|1019|0|0|Undertow:sword;Bloom:spell;Mist Veil:armor
skitter|SKITTER|epic|ward|nature|4|1021|0|0|Quake Stomp:sword;Overgrow:spell;Bulwark:armor
spider-02|GIANT SPIDER|common|nature|feral|2|1022|0|0|Thorn Lash:sword;Pollen Burst:spell
crossbownes|CROSSBOWNES|uncommon|nature|dark|3|1063|0|0|Sting:sword;Dread:spell
ribby-ranger|RIBBY RANGER|uncommon|nature|dark|3|1073|0|0|Root Snap:sword;Dread:spell
skeleton-hermit|SKELETON HERMIT|rare|nature|dark|3|1074|0|0|Bramble Jab:sword;Hex:spell;Bark Skin:armor
old-dwarf|OLD DWARF|common|feral|spirit|2|1130|0|0|Gnaw:sword;Haunt:spell
townsfolk|TOWNSFOLK|common|fire|spirit|2|1135|0|0|Blaze Fang:sword;Phase:armor
archer|ARCHER|uncommon|nature|spirit|3|1136|0|0|Root Snap:sword;Ether Guard:armor
a-single-gorilla|A SINGLE GORILLA|rare|ward|feral|3|1152|0|0|Hammer Down:sword;Snarl:spell;Bulwark:armor
beholder|BEHOLDER|legendary|tide|dark|4|1248|0|0|Bite:sword;Eye Beam:spell;Glare:armor
ghoul-king|GHOUL KING|rare|feral|ward|3|1249|0|0|Fang:sword;War Cry:spell;Curl Up:armor
minotaur-2228|MINOTAUR|rare|feral|ward|3|1275|0|0|Bite:sword;War Cry:spell;Curl Up:armor
minotaura|MINOTAURA|rare|feral|ward|3|1276|0|0|Bite:sword;Rune Rock:spell;Dodge:armor
minotauraga|MINOTAURAGA|rare|feral|ward|3|1277|0|0|Rend:sword;Sandstorm:spell;Hide:armor
thagg|THAGG THE MIGHTY|legendary|ward|feral|4|1289|0|0|Strike:sword;Roar:spell;Granite Hide:armor
guard-sword|GUARD|uncommon|ward|spirit|3|1308|0|0|Dive:sword;Sun Flare:spell
moose|UNIBOAR|common|feral|nature|2|1310|0|0|Pounce:sword;Burrow:armor
wrapped-pharaoh|MUMRAH|legendary|dark|spirit|4|1386|0|0|Grim Reap:sword;Aura Burst:spell;Murk:armor
$cat$, E'\n')) as l where btrim(l) <> '') rows
on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, art = excluded.art, sort = excluded.sort,
  rarity = excluded.rarity, element = excluded.element, types = excluded.types, rnd = excluded.rnd, shift = excluded.shift,
  hearts = excluded.hearts, moves = excluded.moves, droppable = true, active = true;
